import{_ as t,C as r,o as n,c as i,E as o,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"A Revisable Work Graph Still Needs Authority Beyond Graph Readiness","description":"","frontmatter":{"title":"A Revisable Work Graph Still Needs Authority Beyond Graph Readiness","date":"2026-08-06","column":"digital-employee","category":"daily","summary":"A computer-use Digital Employee can represent long work as a revisable DAG, but entry into the ready frontier proves dependency readiness, not permission, isolation, or acceptance of consequential effects.","item_id":"Q-20260806-01","source_research_object":"research/analysis/Q-20260806-01-revisable-dag-computer-use.md","source_reading_result":"research/reading/Q-20260806-01-revisable-dag-computer-use.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-06-governed-revisable-work-graph-cover-v2.jpg"},"headers":[],"relativePath":"en/digital-employee/2026-08-06-governed-revisable-work-graph.md","filePath":"en/digital-employee/2026-08-06-governed-revisable-work-graph.md","lastUpdated":1787407830000}'),d={name:"en/digital-employee/2026-08-06-governed-revisable-work-graph.md"};function c(l,e,h,p,u,m){const a=r("ArticleCover");return n(),i("div",null,[o(a,{image:"/assets/covers/daily-2026-08-06-governed-revisable-work-graph-cover-v2.jpg",kicker:"Digital Employee · Daily Research",title:"A Revisable Work Graph Still Needs Authority Beyond Graph Readiness",summary:"A computer-use Digital Employee can represent long work as a revisable DAG, but entry into the ready frontier proves dependency readiness, not permission, isolation, or acceptance of consequential effects.",version:"Q-20260806-01",status:"Daily Runtime V5 · 2026-08-06",languageHref:"/zh/digital-employee/2026-08-06-governed-revisable-work-graph",languageLabel:"中文"}),e[0]||(e[0]=s(' # A Revisable Work Graph Still Needs Authority Beyond Graph Readiness <p>A computer-use Digital Employee can represent long work as a revisable DAG: a manager maintains dependencies, dispatches ready nodes, and rewrites pending work when execution exposes new dependencies. This is more inspectable than a one-time plan hidden in a prompt and better suited to long-horizon, partially observable work.</p><h2 id="central-judgment" tabindex="-1">Central judgment <a class="header-anchor" href="#central-judgment" aria-label="Permalink to &quot;Central judgment&quot;">​</a></h2><p><strong>Graph readiness proves that dependencies are satisfied; it does not prove that execution is authorized.</strong> A node that can change files, operate a business system, or create an external effect also needs independent permission, resource-isolation, application-ownership, and evidence gates.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The sole analytical input is the same-day Research Object authorized for Production. Its evidence boundary points to a completed Reading Result. Production did not return to the Signal Pool or Reading Result to conduct new research and did not introduce new factual material.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The Research Object preserves three structural observations: the work graph can be persisted and revised during execution; independent ready nodes can run concurrently; and findings or files may need to be carried forward when later workers cannot re-observe the original interface. It also preserves counter-evidence: performance gains are not uniform, one benchmark is slower than the single-agent configuration, and the manager remains a potential bottleneck and interpretation authority.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Planning form</th><th>Visible runtime state</th><th>Parallelism</th><th>Authority and evidence</th><th>Recovery boundary</th></tr></thead><tbody><tr><td>Hidden linear plan</td><td>Low; mostly inside context</td><td>Weak</td><td>Usually mixed with the execution narrative</td><td>Difficult to replay</td></tr><tr><td>Revisable DAG</td><td>Graph versions, nodes, and dependencies are visible</td><td>Ready-frontier scheduling</td><td>The graph does not prove permission or acceptance</td><td>Partial reconstruction from snapshots and logs</td></tr><tr><td>Governed work graph</td><td>Orchestration state is separated from protocol state</td><td>Only nodes without data, resource, or side-effect conflicts run together</td><td>Every node carries authority limits, an evidence contract, and independent acceptance</td><td>Rebuild from events and receipts for already committed effects</td></tr></tbody></table><p>The first two rows summarize mechanisms described by the Research Object. The third is a Research Center engineering synthesis, not a capability already implemented or validated by the source.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>The important change is not “more agents.” It is making the plan a versioned, inspectable, replayable runtime projection. That projection must not replace task truth, approval rights, or completion evidence. A manager may issue a completion claim, but graph state cannot authorize the manager to approve its own interpretation.</p><p>Parallelism also requires more than data independence. Two nodes may have no explicit dependency and still contend for the same browser session, business record, file path, or external account. A consequential ready frontier must combine dependency readiness with authority conditions.</p><h2 id="engineering-impact" tabindex="-1">Engineering impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering impact&quot;">​</a></h2><p>For Digital Employees, a WorkOrder should project a versioned graph whose nodes declare responsibility, dependencies, required skills, authority boundaries, expected artifacts, and completion evidence. Every graph mutation should record actor, reason, before-and-after version, and affected pending nodes.</p><p>For CodeFlowMu, FCoP TASK/REPORT/REVIEW state should remain authoritative while the mutable project graph serves orchestration. Graph versions, mutation events, node evidence receipts, and recovery projections should come before unrestricted parallel computer-use execution.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The evidence is bounded to a June 2026 preprint and related implementation material. It does not establish enterprise authorization, transaction boundaries, safe concurrent side effects, crash-exact recovery, or independent completion acceptance. Some evaluations use LLM or rubric judges, and the parallel configuration is not faster on every benchmark.</p><h2 id="future-work" tabindex="-1">Future work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future work&quot;">​</a></h2><p>The next tests should define a minimum graph-mutation contract, combine permission and dependency readiness, determine whether completed nodes remain valid after downstream rewiring, and distinguish safe replay from an external effect that already occurred.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The visual separates the revisable graph, ready frontier, authority gate, and evidence acceptance. It is a Research Center synthesis based on the Research Object and does not encode unsupported quantitative results.</p><h2 id="evidence-and-references" tabindex="-1">Evidence and references <a class="header-anchor" href="#evidence-and-references" aria-label="Permalink to &quot;Evidence and references&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260806-01-revisable-dag-computer-use.md" target="_blank" rel="noreferrer">Research Object</a>: the sole analytical input, including judgment, uncertainty, counter-evidence, and engineering impact.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260806-01-revisable-dag-computer-use.md" target="_blank" rel="noreferrer">Reading Result</a>: the evidence boundary and source-traceability record declared by the Research Object; this article does not re-analyze it.</li></ol>',25))])}const v=t(d,[["render",c]]);export{g as __pageData,v as default};
